Here is the source code:
<source_code>
#include <bits/stdc++.h>

using namespace std;

template<class T, class U>
void ckmin(T &a, U b)
{
	if (a > b) a = b;
}
template<class T, class U>
void ckmax(T &a, U b)
{
	if (a < b) a = b;
}

#define MP make_pair
#define PB push_back
#define LB lower_bound
#define UB upper_bound
#define fi first
#define se second
#define FOR(i, a, b) for (auto i = (a); i < (b); i++)
#define FORD(i, a, b) for (auto i = (a) - 1; i >= (b); i--)
#define SZ(x) ((int) ((x).size()))
#define ALL(x) (x).begin(), (x).end()
#define INF 1000000007
#define LLINF 2696969696969696969ll

typedef long long ll;
typedef long double ld;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;
typedef vector<int> vi;
typedef vector<ll> vl;
typedef vector<pii> vpi;
typedef vector<pll> vpl;
typedef vector<vl> mat;

ll N, K;
vi num;
mat trans;
mat base[60][30], pref[60][30], suf[60][30];
ll ans;

mat mat_mul(mat a, mat b)
{
	mat res(K + 1);
	FOR(i, 0, K + 1) res[i].resize(K + 1);
	FOR(i, 0, K + 1)
	{
		FOR(j, 0, K + 1)
		{
			res[i][j] = 0;
			FOR(k, 0, K + 1)
			{
				res[i][j] += a[i][k] * b[k][j];
				res[i][j] %= INF;
			}
		}
	}
	return res;
}
mat shift(mat a, int x)
{
	mat res(K + 1);
	FOR(i, 0, K + 1) res[i].resize(K + 1);
	FOR(i, 0, K + 1)
	{
		FOR(j, 0, K + 1)
		{
			if (a[i][j] == 0) continue;
			if (i == j) res[i][j] = a[i][j];
			else res[i][(j + x) % K] = a[i][j];
		}
	}
	return res;
}

int32_t main()
{
	ios_base::sync_with_stdio(0); cin.tie(0);
	cin >> N >> K;
	while(N)
	{
		num.PB(N % K);
		N /= K;
	}
	// for (int x : num)
	// {
	// 	cerr << x << ' ';
	// }
	// cerr << endl;
	FOR(i, 0, K)
	{
		base[0][i].resize(K + 1);
		FOR(j, 0, K + 1) base[0][i][j].resize(K + 1);
		FOR(j, 0, K + 1)
		{
			base[0][i][j][j] = 1;
		}
		FOR(j, 0, K + 1)
		{
			base[0][i][j][i] = 1;
		}
	}
	FOR(i, 1, SZ(num))
	{
		pref[i - 1][0] = base[i - 1][0];
		FOR(j, 1, K)
		{
			pref[i - 1][j] = mat_mul(pref[i - 1][j - 1], base[i - 1][j]);
		}
		suf[i - 1][K - 1] = base[i - 1][K - 1];
		FORD(j, K - 1, 0)
		{
			suf[i - 1][j] = mat_mul(base[i - 1][j], suf[i - 1][j + 1]);
		}
		base[i][0] = pref[i - 1][K - 1];
		FOR(j, 1, K)
		{
			base[i][j] = mat_mul(suf[i - 1][j], pref[i - 1][j - 1]);
		}
	}
	trans.resize(K + 1);
	FOR(i, 0, K + 1) trans[i].resize(K + 1);
	FOR(i, 0, K + 1)
	{
		FOR(j, 0, K + 1)
		{
			trans[i][j] = 0;
		}
		trans[i][i] = 1;
	}
	int sum = 0;
	FORD(i, SZ(num), 0)
	{
		int x = num[i];
		//multiply by
		FOR(j, 0, x)
		{
			trans = mat_mul(trans, base[i][sum]);
			sum++; if (sum >= K) sum -= K;
		}
	}
	ans = 1;
	FOR(i, 0, K)
	{
		ans += trans[K][i];
		ans %= INF;
	}
	cout << ans << '\n';
	return 0;
	//base[i] tells you the transition matrix for 0....k^i - 1
	//trans has the transition matrix for 1!
}

